library(tidyverse)

scriptures &lt;- read_csv("https://github.com/beandog/lds-scriptures/raw/master/csv/lds-scriptures.csv")
savior &lt;- read_rds("https://byuistats.github.io/M335/data/BoM_SaviorNames.rds")

savior_regex &lt;- savior |&gt;
  arrange(desc(nchar)) |&gt;
  pull(name) |&gt;
  unique() |&gt;
  str_c(collapse = "|")

savior_regex &lt;- paste0("\\b(", savior_regex, ")\\b")

# chronological order
bom_levels &lt;- scriptures |&gt;
  filter(volume_title == "Book of Mormon") |&gt;
  pull(book_title) |&gt;
  unique()

book_distances &lt;- scriptures |&gt;
  filter(volume_title == "Book of Mormon") |&gt;
  mutate(book_title = factor(book_title, levels = bom_levels)) |&gt;   # don't sort alphabetically later
  group_by(book_title) |&gt;
  summarize(book_text = str_c(scripture_text, collapse = " "), .groups = "drop") |&gt;
  mutate(
    words_between = map(book_text, \(text) {
      split_text &lt;- str_split(text, pattern = savior_regex) |&gt; unlist()

      # drop the first and last chunks 
      if(length(split_text) &gt; 2) {
        chunks_between &lt;- split_text[-c(1, length(split_text))]
        str_count(chunks_between, "\\S+")
      } else {
        numeric(0)
      }
    })
  ) |&gt;

  # unnest in each row
  unnest(words_between)

